var box = document.getElementById('box');
function val() { return document.getElementById('in').value; }
document.getElementById('good').onclick = function () {
  box.textContent = val();
  document.getElementById('note').textContent = 'Shown as plain text - harmless.';
};
document.getElementById('bad').onclick = function () {
  document.getElementById('note').textContent = 'innerHTML would parse the markup and run the handler. We only show an escaped preview here:';
  box.textContent = '[parsed as HTML] ' + val();
};

