document.getElementById('f').addEventListener('submit', function (e) {
  e.preventDefault();
  document.getElementById('thanks').textContent = ' Thanks, ' + document.getElementById('un').value + '! Message received.';
});

document.getElementById('f').addEventListener('submit', function (e) {
  e.preventDefault();
  var lines = [];
  new FormData(e.target).forEach(function (v, k) { lines.push(k + ' = ' + v); });
  document.getElementById('out').textContent = lines.join('\n');
});
